use rig::prelude::*;
use serde::{Deserialize, Serialize};
use rig::providers::openai::{self, OpenAI};


#[derive(Embed, Clone, Serialize, Deserialize, Debug)]
struct WordDefinition {
    id: String,
    #[embed]
    definition: String,
}


#[tokio::main]
async fn main() -> Result<(), anyhow::Error> {
    let model = OpenAI::from_env()?.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);


    let documents = vec![
        WordDefinition { id: "doc0".into(), definition: "A flurbo is a green alien.".into() },
        WordDefinition { id: "doc1".into(), definition: "A glarb-glarb is an ancient farming tool.".into() },
    ];


    // Embed each document's `#[embed]` field.
    let embeddings = EmbeddingsBuilder::new(model.clone())
        .documents(documents)?
        .build()
        .await?;


    // Store the documents and build an index that embeds queries with the same model.
    let index = InMemoryVectorStore::from_documents(embeddings).index(model);


    let req = VectorSearchRequest::builder()
        .query("What is a flurbo?")
        .samples(1)
        .build();


    for result in index.top_n::<WordDefinition>(req).await? {
        println!("{:.3} {}: {}", result.score, result.id, result.document.definition);
    }


    Ok(())
}

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


#[derive(Embed, Clone, Serialize, Deserialize)]
struct Document {
    id: String,
    #[embed]
    content: String,
}


let model = OpenAI::from_env()?.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);
let docs = vec![Document { id: "doc0".into(), content: "Rig is a Rust library.".into() }];


let embeddings: Vec<(Document, Vec<rig::embeddings::Embedding>)> =
    EmbeddingsBuilder::new(model)
        .documents(docs)?
        .build()
        .await?;

pub trait VectorStoreIndex: Send + Sync {
    /// The backend's filter type.
    type Filter: SearchFilter + Send + Sync;


    /// The top `samples` documents, most similar first, deserialized as `T`.
    async fn top_n<T: DeserializeOwned + Send>(
        &self,
        req: VectorSearchRequest<Self::Filter>,
    ) -> Result<Vec<VectorSearchResult<T>>, VectorStoreError>;


    /// The same ranking, ids and scores only.
    async fn top_n_ids(
        &self,
        req: VectorSearchRequest<Self::Filter>,
    ) -> Result<Vec<VectorSearchIdResult>, VectorStoreError>;
}


pub struct VectorSearchResult<T> {
    pub score: f64,   // scale and direction follow the backend's metric
    pub id: String,
    pub document: T,
}

pub trait InsertDocuments: Send + Sync {
    async fn insert_documents<Doc: Serialize + Embed + Send>(
        &self,
        documents: Vec<(Doc, Vec<Embedding>)>,
    ) -> Result<(), VectorStoreError>;
}

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


let client = OpenAI::from_env()?;
let index = InMemoryVectorStore::<String>::default()
    .index(client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None));


let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
    .preamble("Search the knowledge base before answering.")
    .tool(index)
    .build();
